import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

class AppLanguage {
  final String code; final String name;
  const AppLanguage(this.code, this.name);
}

class AppLocaleController {
  AppLocaleController._();
  static final instance = AppLocaleController._();
  static const _key = 'app_language';
  final ValueNotifier<Locale?> locale = ValueNotifier<Locale?>(null);
  Future<void> load() async { final p=await SharedPreferences.getInstance(); final c=p.getString(_key); if(c!=null) locale.value=_toLocale(c); }
  Future<void> setLanguage(String code) async { final p=await SharedPreferences.getInstance(); await p.setString(_key,code); locale.value=_toLocale(code); }
  Locale _toLocale(String c){ final p=c.split('_'); return p.length>1?Locale(p[0],p[1]):Locale(p[0]); }
}

